class Solution:
    def removeDuplicateLetters(self, s: str) -> str:
        count = [0] * 26
        for ch in s:
            count[ord(ch) - 97] += 1

        stack = []
        used = [False] * 26

        for ch in s:
            idx = ord(ch) - 97
            count[idx] -= 1

            if used[idx]:
                continue

            while stack:
                top_idx = ord(stack[-1]) - 97
                if stack[-1] <= ch or count[top_idx] == 0:
                    break
                used[top_idx] = False
                stack.pop()

            stack.append(ch)
            used[idx] = True

        return ''.join(stack)

