#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

char* removeDuplicateLetters(const char* s) {
    size_t n = strlen(s);
    int count[26] = {0};
    bool used[26] = {false};

    for (size_t i = 0; i < n; ++i) {
        ++count[s[i] - 'a'];
    }

    char* stack = (char*)malloc(n + 1);
    if (stack == NULL) return NULL;

    size_t top = 0;

    for (size_t i = 0; i < n; ++i) {
        char ch = s[i];
        int idx = ch - 'a';
        --count[idx];

        if (used[idx]) continue;

        while (top > 0) {
            char last = stack[top - 1];
            int lastIdx = last - 'a';
            if (last <= ch || count[lastIdx] == 0) break;
            used[lastIdx] = false;
            --top;
        }

        stack[top++] = ch;
        used[idx] = true;
    }

    stack[top] = '\0';
    return stack;
}

