class Solution {
public:
    string removeDuplicateLetters(string s) {
        int count[26] = {};
        for (char ch : s) {
            ++count[ch - 'a'];
        }

        string stack;
        stack.reserve(s.size());
        bool used[26] = {};

        for (char ch : s) {
            int idx = ch - 'a';
            --count[idx];

            if (used[idx]) continue;

            while (!stack.empty()) {
                char last = stack.back();
                int lastIdx = last - 'a';
                if (last <= ch || count[lastIdx] == 0) break;
                used[lastIdx] = false;
                stack.pop_back();
            }

            stack.push_back(ch);
            used[idx] = true;
        }

        return stack;
    }
};

