class Solution {
    public String removeDuplicateLetters(String s) {
        int[] count = new int[26];
        for (int i = 0; i < s.length(); i++) {
            count[s.charAt(i) - 'a']++;
        }

        char[] stack = new char[s.length()];
        int top = 0;
        boolean[] used = new boolean[26];

        for (int i = 0; i < s.length(); i++) {
            char ch = s.charAt(i);
            int idx = ch - 'a';
            count[idx]--;

            if (used[idx]) {
                continue;
            }

            while (top > 0) {
                char last = stack[top - 1];
                int lastIdx = last - 'a';
                if (last <= ch || count[lastIdx] == 0) {
                    break;
                }
                used[lastIdx] = false;
                top--;
            }

            stack[top++] = ch;
            used[idx] = true;
        }

        return new String(stack, 0, top);
    }
}

